const raw = $json.mensagens || [];
const parsed = raw.map(x => {
  try { return typeof x === 'string' ? JSON.parse(x) : x; } catch (e) { return null; }
}).filter(Boolean);
parsed.sort((a, b) => new Date(a.recebidoEm) - new Date(b.recebidoEm));
const texto = parsed.map(m => (m.texto || '').trim()).filter(Boolean).join(' ');
return [{
  json: {
    numero: $('Extrair dados').item.json.numero,
    texto,
    nome: $('Extrair dados').item.json.nome,
  }
}];
